.partner-types{display:flex;gap:12rpx;margin:16rpx 0}.partner-types button{padding:16rpx;background:#eef2e7;border-radius:18rpx;font-size:23rpx}.partner-types .active{background:#246b50;color:white}.hero{margin:45rpx 0 28rpx}.hero .display-title{display:block;margin-top:10rpx;font-size:49rpx}.requirements,.form{padding:27rpx}.requirements>view{display:grid;grid-template-columns:44rpx 1fr;gap:12rpx;align-items:start;margin-top:18rpx}.requirements>view>text:first-child{width:40rpx;height:40rpx;display:flex;align-items:center;justify-content:center;border-radius:14rpx;background:#246b50;color:#fff;font-size:18rpx;font-weight:900}.requirements>view>text:last-child{font-size:20rpx;line-height:1.55}.review-note{display:block;margin-top:20rpx;padding:15rpx;border-radius:15rpx;background:#edf2e5;color:#51695f;font-size:18rpx}.form{margin-top:20rpx}.form .section-title{display:block;margin-bottom:20rpx}.form .label{display:block;margin-top:13rpx}.field-input{margin-top:8rpx}.text-area{width:100%;height:130rpx;margin-top:8rpx;padding:17rpx;border:1rpx solid #dce2d8;border-radius:16rpx;background:#ffffff;font-size:21rpx}.form .primary-button{margin-top:22rpx}.safe-note{display:block;margin-top:15rpx;text-align:center}</style>
